<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Models\Bank\BankTransaction;use App\Services\Finance\BriConfigurationService;use App\Services\Finance\BriReconciliationService;use Illuminate\Http\Request;class BriReconciliationController extends Controller{public function index(BriConfigurationService $bri){return view('finance.bri.index',['enabled'=>$bri->enabled(),'transactions'=>BankTransaction::latest('occurred_at')->paginate(25)]);}public function transactions(){return $this->index(app(BriConfigurationService::class));}public function reconcile(Request $r,BankTransaction $transaction,BriReconciliationService $s){abort_unless($r->user()->can('finance.bri.reconcile'),403);$s->reconcile($transaction,$r->user()->id);return back()->with('success','Transaksi berhasil direkonsiliasi.');}}
